    adcs_vec3_t unit_axis;
    adcs_vec3_t command_dipole;
    adcs_vec3_t expected_torque;
    double norm_field;
    double norm_expected;
    double norm_measured;
    double projection;
    double alignment_cosine;
    double threshold;

    // Initialize output with safe defaults
    pt_output.mode = pt_state.mode;
    pt_output.command_a_m2.x = 0.0;
    pt_output.command_a_m2.y = 0.0;
    pt_output.command_a_m2.z = 0.0;
    pt_output.expected_torque_nm.x = 0.0;
    pt_output.expected_torque_nm.y = 0.0;
    pt_output.expected_torque_nm.z = 0.0;
    pt_output.projection_nm2 = 0.0;
    pt_output.alignment_cosine = 0.0;

    // 1. Validate Enable (must be 0 or 1)
    if (pt_input.enable != 0 && pt_input.enable != 1) {
        goto fault_latch;
    }

    // 2. Validate Pointers and Finiteness
    if (pt_input.field_body_t == NULL || !adcs_is_finite_vec3(pt_input.field_body_t)) {
        goto fault_latch;
    }
    if (pt_input.measured_torque_nm == NULL || !adcs_is_finite_vec3(pt_input.measured_torque_nm)) {
        goto fault_latch;
    }

    // 3. Validate Config Parameters
    if (!isfinite(pt_config.test_dipole_a_m2) || pt_config.test_dipole_a_m2 <= 0.0) {
        goto fault_latch;
    }
    if (!isfinite(pt_config.min_fraction) || pt_config.min_fraction <= 0.0 || pt_config.min_fraction > 1.0) {
        goto fault_latch;
    }
    if (pt_config.confirm_samples < 1 || pt_config.confirm_samples > 20) {
        goto fault_latch;
    }
    if (pt_config.max_samples_per_phase < 1 || pt_config.max_samples_per_phase > 200) {
        goto fault_latch;
    }

    // 4. Handle Disable
    if (pt_input.enable == 0) {
        pt_state.mode = PT_IDLE;
        pt_state.confirm_count = 0;
        pt_state.sample_count = 0;

        pt_output.mode = PT_IDLE;
        pt_output.command_a_m2.x = 0.0;
        pt_output.command_a_m2.y = 0.0;
        pt_output.command_a_m2.z = 0.0;
        pt_output.expected_torque_nm.x = 0.0;
        pt_output.expected_torque_nm.y = 0.0;
        pt_output.expected_torque_nm.z = 0.0;
        pt_output.projection_nm2 = 0.0;
        pt_output.alignment_cosine = 0.0;
        return;
    }

    // 5. Normalize Test Axis
    if (adcs_vec3_normalize(&pt_config.test_axis_body, ADCS_EPS_NORM, &unit_axis) != ADCS_OK) {
        goto fault_latch;
    }

    // 6. Handle Latched States (PASS/FAULT)
    // If already latched, remain latched, command is zero.
    // Inputs are assumed valid (checked above), but no state change occurs.
    if (pt_state.mode == PT_PASS || pt_state.mode == PT_FAULT) {
        pt_output.mode = pt_state.mode;
        pt_output.command_a_m2.x = 0.0;
        pt_output.command_a_m2.y = 0.0;
        pt_output.command_a_m2.z = 0.0;
        pt_output.expected_torque_nm.x = 0.0;
        pt_output.expected_torque_nm.y = 0.0;
        pt_output.expected_torque_nm.z = 0.0;
        pt_output.projection_nm2 = 0.0;
        pt_output.alignment_cosine = 0.0;
        return;
    }

    // 7. Compute Expected Torque for Current Phase
    // IDLE uses positive dipole, NEGATIVE uses negative dipole
    double sign = (pt_state.mode == PT_NEGATIVE) ? -1.0 : 1.0;
    command_dipole = adcs_vec3_scale(&unit_axis, sign * pt_config.test_dipole_a_m2);

    expected_torque = adcs_vec3_cross(&command_dipole, pt_input.field_body_t);
    norm_expected = adcs_vec3_norm(&expected_torque);

    // 8. Check Geometry Validity
    norm_field = adcs_vec3_norm(pt_input.field_body_t);
    norm_measured = adcs_vec3_norm(pt_input.measured_torque_nm);

    if (norm_field <= ADCS_EPS_NORM || norm_expected <= ADCS_EPS_NORM || norm_measured <= ADCS_EPS_NORM) {
        goto fault_latch;
    }

    // 9. Compute Projection and Alignment Cosine
    projection = adcs_vec3_dot(pt_input.measured_torque_nm, &expected_torque);
    alignment_cosine = projection / (norm_measured * norm_expected);

    // 10. Check Projection Adequacy
    // "projection is at least min_fraction times the expected squared norm"
    threshold = pt_config.min_fraction * (norm_expected * norm_expected);
    int is_projection_adequate = (projection >= threshold) ? 1 : 0;

    // 11. State Transition Logic
    if (is_projection_adequate) {
        pt_state.confirm_count++;
        pt_state.sample_count = 0; // Reset sample counter

        if (pt_state.confirm_count >= pt_config.confirm_samples) {
            // Advance Phase
            if (pt_state.mode == PT_IDLE) {
                pt_state.mode = PT_NEGATIVE;
            } else if (pt_state.mode == PT_NEGATIVE) {
                pt_state.mode = PT_PASS;
            }
            // Reset counters after advancing
            pt_state.confirm_count = 0;
            pt_state.sample_count = 0;
        }
    } else {
        pt_state.confirm_count = 0; // Reset confirmation counter
        pt_state.sample_count++;    // Increment sample counter

        if (pt_state.sample_count >= pt_config.max_samples_per_phase) {
            // Timeout -> Latch FAULT
            pt_state.mode = PT_FAULT;
            pt_state.confirm_count = 0;
            pt_state.sample_count = 0;
        }
    }

    // 12. Finalize Output Command based on NEW mode
    // "The published command_a_m2 is the command of the mode after this cycle's transition"
    if (pt_state.mode == PT_PASS || pt_state.mode == PT_FAULT) {
        pt_output.command_a_m2.x = 0.0;
        pt_output.command_a_m2.y = 0.0;
        pt_output.command_a_m2.z = 0.0;
    } else if (pt_state.mode == PT_IDLE) {
        pt_output.command_a_m2 = adcs_vec3_scale(&unit_axis, pt_config.test_dipole_a_m2);
    } else if (pt_state.mode == PT_NEGATIVE) {
        pt_output.command_a_m2 = adcs_vec3_scale(&unit_axis, -pt_config.test_dipole_a_m2);
    }

    // 13. Assign Other Outputs
    pt_output.mode = pt_state.mode;
    pt_output.expected_torque_nm = expected_torque;
    pt_output.projection_nm2 = projection;
    pt_output.alignment_cosine = alignment_cosine;
    return;

fault_latch:
    pt_state.mode = PT_FAULT;
    pt_state.confirm_count = 0;
    pt_state.sample_count = 0;

    pt_output.mode = PT_FAULT;
    pt_output.command_a_m2.x = 0.0;
    pt_output.command_a_m2.y = 0.0;
    pt_output.command_a_m2.z = 0.0;
    pt_output.expected_torque_nm.x = 0.0;
